# Role: object — Format E MC encode→disasm stress for core LS / ALU32 / ALU64 ops.

# Format E MC encode→disasm stress for core LS / ALU32 / ALU64 ops.

# Absolute PCs are not pinned (12-byte packets). CHECK matches mnemonics

# and operands in order. Phantom mul32 / broken WideImm slli64 forms removed.

# Dedicated LD16/LD8 gate: ld16-ld8-format-e-roundtrip.s
# HI12/LO20 gate: cb76-reloc-hi20-lo16.s
#

# Note: objdump may omit spaces between mnemonic and first operand
# (ld16r3 …). Patterns use {{.*}} flex.


#===----------------------------------------------------------------------===

# Load / store

#===----------------------------------------------------------------------===



ld32 r0, r1, 0

ld32 r2, r3, 4

ld32 r4, r5, -4


ld16 r3, r4, 0

ld16 r5, r6, 2

ldu16 r11, r12, 0

st16 r2, r3, 0


ld8 r10, r11, 0

ldu8 r5, r6, 0

st8 r9, r10, 0


ld64 d0, r4, 0

st64 d0, r8, 0


#===----------------------------------------------------------------------===

# ALU32

#===----------------------------------------------------------------------===


add32 r0, r1, r2

addi32 r3, r4, 0

addi32 r5, r6, 32767

# 1 in RI20 prints as signed decimal

addi32 r7, r8, -1

andi32 r9, r10, 65535

slli32 r0, r1, 0

slli32 r2, r3, 31

# LUI is HI12 (0..4095), not legacy HI20

lui r4, 0

lui r5, 4095

not32 r3, r4

move32 r5, r6

slt32 r10, r11, r12

neg32 r1, r2

nsa32 r12, r0


#===----------------------------------------------------------------------===

# ALU64 / SIMD

#===----------------------------------------------------------------------===


add64 d0, d1, d2

add64 d15, d0, d1

xor64 d0, d1, d2

x2add32 d9, d10, d11

x4add16 d2, d3, d4

x2mul32 d15, d0, d1, d2


#===----------------------------------------------------------------------===

# CSR

#===----------------------------------------------------------------------===


csrr r2, 0

csrw 0, r4

